  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.glass-card {
  background: linear-gradient(135deg, rgba(30, 41, 59, 0.65) 0%, rgba(15, 23, 42, 0.85) 100%);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.07);
  transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}

.glass-card:hover {
  transform: translateY(-3px);
  border-color: rgba(99, 102, 241, 0.35);
  box-shadow: 0 12px 28px -8px rgba(0, 0, 0, 0.5), 0 0 20px -3px rgba(99, 102, 241, 0.18);
}

/* Custom Scrollbars */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.6);
}

::-webkit-scrollbar-thumb {
  background: rgba(71, 85, 105, 0.5);
  border-radius: 9999px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(100, 116, 139, 0.8);
}

.scrollbar-none::-webkit-scrollbar {
  display: none;
}
.scrollbar-none {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Status Indicator Dots */
.status-dot-online {
  background-color: #10b981;
  box-shadow: 0 0 8px #10b981;
}

.status-dot-degraded {
  background-color: #f59e0b;
  box-shadow: 0 0 8px #f59e0b;
}

.status-dot-offline {
  background-color: #ef4444;
  box-shadow: 0 0 8px #ef4444;
}

.status-dot-unknown {
  background-color: #64748b;
}

/* Shimmer animation for loading states */
@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.loading-shimmer {
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.03) 25%, rgba(255, 255, 255, 0.08) 50%, rgba(255, 255, 255, 0.03) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

/* Operational roadmap */
.roadmap-stat {
  min-height: 90px;
  padding: 0.85rem 1rem;
  border: 1px solid rgba(51, 65, 85, 0.8);
  border-radius: 0.9rem;
  background: rgba(15, 23, 42, 0.65);
}

.roadmap-stat-label,
.roadmap-stat-note {
  display: block;
  color: #94a3b8;
  font-family: var(--font-mono);
  font-size: 0.65rem;
}

.roadmap-stat strong {
  display: block;
  margin: 0.25rem 0;
  color: #f8fafc;
  font-size: 1.25rem;
}

.roadmap-stat-note {
  color: #64748b;
  font-size: 0.58rem;
}

.roadmap-card {
  border: 1px solid rgba(51, 65, 85, 0.85);
  border-radius: 1rem;
  background: linear-gradient(135deg, rgba(30, 41, 59, 0.72), rgba(15, 23, 42, 0.9));
  transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

.roadmap-card:hover,
.roadmap-card:focus-within {
  border-color: rgba(34, 211, 238, 0.55);
  box-shadow: 0 10px 24px -12px rgba(34, 211, 238, 0.4);
  transform: translateY(-2px);
}

.roadmap-card > button {
  padding: 1rem;
}

.roadmap-id {
  color: #67e8f9;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 600;
}

.roadmap-list {
  display: grid;
  gap: 0.35rem;
}

.roadmap-list-item {
  border: 1px solid rgba(51, 65, 85, 0.75);
  border-radius: 0.7rem;
  background: rgba(15, 23, 42, 0.62);
  transition: border-color 0.2s ease, background 0.2s ease;
}

.roadmap-list-item:hover,
.roadmap-list-item:focus-within {
  border-color: rgba(34, 211, 238, 0.5);
  background: rgba(30, 41, 59, 0.78);
}

.roadmap-list-button {
  display: grid;
  width: 100%;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0.8rem;
  text-align: left;
}

.roadmap-list-status {
  color: #67e8f9;
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
}

.roadmap-list-main,
.roadmap-list-heading,
.roadmap-list-meta {
  display: flex;
  min-width: 0;
  align-items: center;
}

.roadmap-list-main {
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
}

.roadmap-list-heading {
  width: 100%;
  gap: 0.6rem;
}

.roadmap-list-title {
  overflow: hidden;
  color: #e2e8f0;
  font-size: 0.78rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roadmap-list-meta {
  flex-wrap: wrap;
  gap: 0.55rem;
  color: #64748b;
  font-family: var(--font-mono);
  font-size: 0.58rem;
}

.roadmap-list-tail {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.35rem;
  color: #64748b;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  text-align: right;
}

.roadmap-list-count {
  white-space: nowrap;
}

.roadmap-table-intro {
  margin-bottom: 0.6rem;
  color: #64748b;
  font-family: var(--font-mono);
  font-size: 0.65rem;
}

.roadmap-sort-button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: #94a3b8;
  font: inherit;
  text-align: left;
}

.roadmap-sort-button:hover,
.roadmap-sort-button:focus-visible {
  color: #cffafe;
}

.roadmap-sort-indicator {
  color: #22d3ee;
  font-size: 0.8rem;
}

.roadmap-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  border: 1px solid rgba(100, 116, 139, 0.45);
  border-radius: 999px;
  padding: 0.18rem 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  line-height: 1;
}

.roadmap-tag-status {
  border-color: rgba(34, 211, 238, 0.35);
  color: #a5f3fc;
  background: rgba(8, 145, 178, 0.12);
}

.roadmap-tag-neutral {
  color: #94a3b8;
  background: rgba(51, 65, 85, 0.25);
}

.roadmap-tag-warning {
  border-color: rgba(251, 191, 36, 0.4);
  color: #fcd34d;
  background: rgba(146, 64, 14, 0.15);
}

.roadmap-state-symbol {
  color: #67e8f9;
  font-family: var(--font-mono);
  font-size: 1.2rem;
  font-weight: 700;
}

.roadmap-mode-button {
  border-radius: 0.65rem;
  padding: 0.45rem 0.8rem;
  color: #94a3b8;
  font-family: var(--font-mono);
  font-size: 0.7rem;
}

.roadmap-mode-button:hover,
.roadmap-mode-active {
  color: #cffafe;
  background: rgba(8, 145, 178, 0.25);
}

.roadmap-alert {
  border: 1px solid rgba(100, 116, 139, 0.45);
  border-radius: 0.8rem;
  padding: 0.65rem 0.8rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
}

.roadmap-alert-neutral { color: #94a3b8; background: rgba(51, 65, 85, 0.2); }
.roadmap-alert-success { color: #86efac; border-color: rgba(34, 197, 94, 0.35); background: rgba(20, 83, 45, 0.18); }
.roadmap-alert-warning { color: #fde68a; border-color: rgba(245, 158, 11, 0.4); background: rgba(120, 53, 15, 0.2); }
.roadmap-alert-error { color: #fda4af; border-color: rgba(244, 63, 94, 0.4); background: rgba(127, 29, 29, 0.2); }

.roadmap-empty-state {
  border: 1px dashed rgba(100, 116, 139, 0.5);
  border-radius: 1rem;
  padding: 2rem;
  color: #94a3b8;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}

.roadmap-source-pill {
  border: 1px solid rgba(34, 211, 238, 0.25);
  border-radius: 999px;
  padding: 0.25rem 0.5rem;
  color: #94a3b8;
  background: rgba(8, 145, 178, 0.08);
}

.roadmap-detail-heading {
  margin-bottom: 0.45rem;
  color: #94a3b8;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.roadmap-detail-list {
  display: grid;
  gap: 0.4rem;
  padding-left: 1rem;
  color: #cbd5e1;
  font-size: 0.72rem;
  list-style: disc;
}

.roadmap-timeline-intro,
.roadmap-graph-intro {
  margin-bottom: 0.8rem;
  color: #64748b;
  font-family: var(--font-mono);
  font-size: 0.68rem;
}

.roadmap-timeline {
  display: grid;
  grid-template-columns: repeat(5, minmax(170px, 1fr));
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 0.4rem;
}

.roadmap-timeline-column {
  min-height: 190px;
  padding: 0.85rem;
  border: 1px solid rgba(51, 65, 85, 0.8);
  border-radius: 1rem;
  background: rgba(15, 23, 42, 0.55);
}

.roadmap-timeline-item {
  border-left: 2px solid rgba(34, 211, 238, 0.55);
  border-radius: 0.6rem;
  background: rgba(30, 41, 59, 0.65);
}

.roadmap-timeline-item:hover,
.roadmap-timeline-item:focus-within {
  background: rgba(30, 41, 59, 0.95);
}

.roadmap-timeline-item button {
  padding: 0.65rem;
}

.roadmap-graph-shell {
  max-width: 100%;
  overflow: auto;
  border: 1px solid rgba(51, 65, 85, 0.8);
  border-radius: 1rem;
  background: radial-gradient(circle at top, rgba(8, 145, 178, 0.08), rgba(15, 23, 42, 0.8) 55%);
}

.roadmap-graph {
  display: block;
  min-width: 1050px;
  min-height: 170px;
  padding: 0.75rem;
}

.roadmap-graph-edge {
  fill: none;
  stroke: #22d3ee;
  stroke-opacity: 0.42;
  stroke-width: 1.5;
}

.roadmap-graph-node {
  cursor: pointer;
  outline: none;
}

.roadmap-graph-node:focus rect,
.roadmap-graph-node:hover rect {
  stroke: #f8fafc;
  stroke-width: 2;
}

@media (max-width: 900px) {
  .roadmap-timeline { grid-template-columns: repeat(5, minmax(190px, 1fr)); }
}

@media (max-width: 640px) {
  .roadmap-list-button { grid-template-columns: auto minmax(0, 1fr); }
  .roadmap-list-tail { grid-column: 2; justify-content: flex-start; text-align: left; }
  .roadmap-list-heading { align-items: flex-start; flex-direction: column; gap: 0.15rem; }
}

@media (prefers-reduced-motion: reduce) {
  .roadmap-card { transition: none; }
  .roadmap-card:hover,
  .roadmap-card:focus-within { transform: none; }
  .roadmap-list-item { transition: none; }
}
